-- Replay is idempotent; no changes to financial, schedule, numbering or document metadata.
BEGIN;
DO $d55$ DECLARE r jsonb; current_row jsonb; BEGIN
IF public.pm_project_b1_active() THEN RAISE EXCEPTION 'B1 must remain OFF'; END IF;
FOR r IN SELECT value FROM jsonb_array_elements('[{"before": {"id": "e878c2de-973c-40c0-a7fe-d93fdd9f0d00", "title": "Sumário da proposta", "is_locked": false, "block_type": "about", "created_at": "2026-11-07T18:55:18.931981+00:00", "is_visible": true, "sort_order": 30, "source_ref": {}, "updated_at": "2026-11-13T14:10:00.268338+00:00", "proposal_id": "3d0db6b3-4bf5-4681-a875-c553f8c64656", "source_type": "library", "content_rich": {"html": "<p>A presente proposta descreve os serviços de arquitetura da Pedra Silva Arquitectos, enquanto projectistas, para a reabilitação do edifício da Rua Nova do Almada, 63-73, em Lisboa, e a sua conversão em hotel.</p><p>A prestação de serviços abrange todo o processo de projeto – Programa, Estudo Prévio, Anteprojeto e Pedido de Informação Prévia, Projeto de Licenciamento e Projeto de Execução – bem como a Assistência Técnica à Obra.</p><h3>Pressupostos principais</h3><ul><li><p>Desenvolvimento de projecto de arquitectura em conjunto com parceiro de Interior Design a indicar pelo cliente</p></li><li><p>Licenciamento como empreendimento turístico, na tipologia de estabelecimento hoteleiro;</p></li><li><p>Projetos de especialidades contratados diretamente pelo promotor e coordenados pela Pedra Silva Arquitectos.</p></li></ul><p>Os honorários, o planeamento e as condições de pagamento são apresentados nos capítulos seguintes.</p>", "text": "A presente proposta descreve os serviços de arquitetura da Pedra Silva Arquitectos, enquanto projectistas, para a reabilitação do edifício da Rua Nova do Almada, 63-73, em Lisboa, e a sua conversão em hotel.\n\nA prestação de serviços abrange todo o processo de projeto – Programa, Estudo Prévio, Anteprojeto e Pedido de Informação Prévia, Projeto de Licenciamento e Projeto de Execução – bem como a Assistência Técnica à Obra.\n\nPressupostos principais\n\n\n\n\n\nDesenvolvimento de projecto de arquitectura em conjunto com parceiro de Interior Design a indicar pelo cliente\n\n\n\nLicenciamento como empreendimento turístico, na tipologia de estabelecimento hoteleiro;\n\n\n\nProjetos de especialidades contratados diretamente pelo promotor e coordenados pela Pedra Silva Arquitectos.\n\nOs honorários, o planeamento e as condições de pagamento são apresentados nos capítulos seguintes."}, "contract_relevance": "proposal_only"}, "after": {"block_type": "about", "content_rich": {"headingLevel": "h1", "html": "<p>A presente proposta descreve os serviços de arquitetura da Pedra Silva Arquitectos, enquanto projectistas, para a reabilitação do edifício da Rua Nova do Almada, 63-73, em Lisboa, e a sua conversão em hotel.</p><p>A prestação de serviços abrange todo o processo de projeto – Programa, Estudo Prévio, Anteprojeto e Pedido de Informação Prévia, Projeto de Licenciamento e Projeto de Execução – bem como a Assistência Técnica à Obra.</p><h3>Pressupostos principais</h3><ul><li><p>Desenvolvimento de projecto de arquitectura em conjunto com parceiro de Interior Design a indicar pelo cliente</p></li><li><p>Licenciamento como empreendimento turístico, na tipologia de estabelecimento hoteleiro;</p></li><li><p>Projetos de especialidades contratados diretamente pelo promotor e coordenados pela Pedra Silva Arquitectos.</p></li></ul><p>Os honorários, o planeamento e as condições de pagamento são apresentados nos capítulos seguintes.</p>", "text": "A presente proposta descreve os serviços de arquitetura da Pedra Silva Arquitectos, enquanto projectistas, para a reabilitação do edifício da Rua Nova do Almada, 63-73, em Lisboa, e a sua conversão em hotel.\n\nA prestação de serviços abrange todo o processo de projeto – Programa, Estudo Prévio, Anteprojeto e Pedido de Informação Prévia, Projeto de Licenciamento e Projeto de Execução – bem como a Assistência Técnica à Obra.\n\nPressupostos principais\n\n\n\n\n\nDesenvolvimento de projecto de arquitectura em conjunto com parceiro de Interior Design a indicar pelo cliente\n\n\n\nLicenciamento como empreendimento turístico, na tipologia de estabelecimento hoteleiro;\n\n\n\nProjetos de especialidades contratados diretamente pelo promotor e coordenados pela Pedra Silva Arquitectos.\n\nOs honorários, o planeamento e as condições de pagamento são apresentados nos capítulos seguintes."}, "contract_relevance": "proposal_only", "created_at": "2026-11-07T18:55:18.931981+00:00", "id": "e878c2de-973c-40c0-a7fe-d93fdd9f0d00", "is_locked": false, "is_visible": true, "proposal_id": "3d0db6b3-4bf5-4681-a875-c553f8c64656", "sort_order": 100, "source_ref": {}, "source_type": "library", "title": "Sumário da proposta", "updated_at": "2026-11-13T14:35:52.189711+00:00"}}, {"before": {"id": "1e683c82-2fbe-408f-b44f-98067e813562", "title": "Porquê a Pedra Silva Arquitectos", "is_locked": false, "block_type": "about", "created_at": "2026-11-12T08:38:56.132506+00:00", "is_visible": true, "sort_order": 40, "source_ref": {}, "updated_at": "2026-11-13T14:10:58.737962+00:00", "proposal_id": "3d0db6b3-4bf5-4681-a875-c553f8c64656", "source_type": "library", "content_rich": {"html": "<h3>Experiência em hotelaria</h3><p>Poucos ateliers de arquitetura conjugam a experiência internacional em hotelaria com um conhecimento profundo do mercado português como a Pedra Silva Arquitectos.</p><p>Há mais de vinte anos que o nosso atelier se dedica ao projeto de hotéis, espaços de trabalho, habitação e projetos de uso misto, onde a qualidade do desenho, a eficiência operacional e a viabilidade comercial são igualmente importantes. A nossa experiência abrange todas as fases do projeto, desde os estudos de viabilidade iniciais até ao licenciamento, projeto de execução, concurso e assistência técnica à obra.</p><h3>Experiência relevante</h3><p>Concluímos recentemente a premiada transformação do Aethos Ericeira num dos principais hotéis boutique de Portugal, reconhecido internacionalmente pela Condé Nast Traveller, pelo Guia MICHELIN e pelos The Plan Awards.</p><p>A Pedra Silva Arquitectos teve ainda um papel central no desenvolvimento técnico da expansão do L''AND Vineyards, no Alentejo, em colaboração com o arquiteto Márcio Kogan (Studio MK27), sendo responsável pelo projeto de execução, documentação de concurso, licenciamento e coordenação com a câmara municipal e os projetistas de especialidades.</p><h3>Os clientes escolhem a Pedra Silva Arquitectos porque conjugamos:</h3><ul><li><p>Experiência internacional em diversos projectos com um forte conhecimento local;</p></li><li><p>Arquitetura e design de interiores integrados quando necessário;</p></li><li><p>Vasta experiência em projeto de execução de edifícios complexos;</p></li><li><p>Coordenação multidisciplinar com os projetistas de especialidades;</p></li><li><p>Experiência comprovada desde o conceito até à conclusão da obra.</p></li></ul><p></p>", "text": "Experiência em hotelaria\n\nPoucos ateliers de arquitetura conjugam a experiência internacional em hotelaria com um conhecimento profundo do mercado português como a Pedra Silva Arquitectos.\n\nHá mais de vinte anos que o nosso atelier se dedica ao projeto de hotéis, espaços de trabalho, habitação e projetos de uso misto, onde a qualidade do desenho, a eficiência operacional e a viabilidade comercial são igualmente importantes. A nossa experiência abrange todas as fases do projeto, desde os estudos de viabilidade iniciais até ao licenciamento, projeto de execução, concurso e assistência técnica à obra.\n\nExperiência relevante\n\nConcluímos recentemente a premiada transformação do Aethos Ericeira num dos principais hotéis boutique de Portugal, reconhecido internacionalmente pela Condé Nast Traveller, pelo Guia MICHELIN e pelos The Plan Awards.\n\nA Pedra Silva Arquitectos teve ainda um papel central no desenvolvimento técnico da expansão do L''AND Vineyards, no Alentejo, em colaboração com o arquiteto Márcio Kogan (Studio MK27), sendo responsável pelo projeto de execução, documentação de concurso, licenciamento e coordenação com a câmara municipal e os projetistas de especialidades.\n\nOs clientes escolhem a Pedra Silva Arquitectos porque conjugamos:\n\n\n\n\n\nExperiência internacional em diversos projectos com um forte conhecimento local;\n\n\n\nArquitetura e design de interiores integrados quando necessário;\n\n\n\nVasta experiência em projeto de execução de edifícios complexos;\n\n\n\nCoordenação multidisciplinar com os projetistas de especialidades;\n\n\n\nExperiência comprovada desde o conceito até à conclusão da obra.\n\n"}, "contract_relevance": "proposal_only"}, "after": {"block_type": "about", "content_rich": {"headingLevel": "h1", "html": "<h3>Experiência em hotelaria</h3><p>Poucos ateliers de arquitetura conjugam a experiência internacional em hotelaria com um conhecimento profundo do mercado português como a Pedra Silva Arquitectos.</p><p>Há mais de vinte anos que o nosso atelier se dedica ao projeto de hotéis, espaços de trabalho, habitação e projetos de uso misto, onde a qualidade do desenho, a eficiência operacional e a viabilidade comercial são igualmente importantes. A nossa experiência abrange todas as fases do projeto, desde os estudos de viabilidade iniciais até ao licenciamento, projeto de execução, concurso e assistência técnica à obra.</p><h3>Experiência relevante</h3><p>Concluímos recentemente a premiada transformação do Aethos Ericeira num dos principais hotéis boutique de Portugal, reconhecido internacionalmente pela Condé Nast Traveller, pelo Guia MICHELIN e pelos The Plan Awards.</p><p>A Pedra Silva Arquitectos teve ainda um papel central no desenvolvimento técnico da expansão do L''AND Vineyards, no Alentejo, em colaboração com o arquiteto Márcio Kogan (Studio MK27), sendo responsável pelo projeto de execução, documentação de concurso, licenciamento e coordenação com a câmara municipal e os projetistas de especialidades.</p><h3>Os clientes escolhem a Pedra Silva Arquitectos porque conjugamos:</h3><ul><li><p>Experiência internacional em diversos projectos com um forte conhecimento local;</p></li><li><p>Arquitetura e design de interiores integrados quando necessário;</p></li><li><p>Vasta experiência em projeto de execução de edifícios complexos;</p></li><li><p>Coordenação multidisciplinar com os projetistas de especialidades;</p></li><li><p>Experiência comprovada desde o conceito até à conclusão da obra.</p></li></ul><p></p>", "text": "Experiência em hotelaria\n\nPoucos ateliers de arquitetura conjugam a experiência internacional em hotelaria com um conhecimento profundo do mercado português como a Pedra Silva Arquitectos.\n\nHá mais de vinte anos que o nosso atelier se dedica ao projeto de hotéis, espaços de trabalho, habitação e projetos de uso misto, onde a qualidade do desenho, a eficiência operacional e a viabilidade comercial são igualmente importantes. A nossa experiência abrange todas as fases do projeto, desde os estudos de viabilidade iniciais até ao licenciamento, projeto de execução, concurso e assistência técnica à obra.\n\nExperiência relevante\n\nConcluímos recentemente a premiada transformação do Aethos Ericeira num dos principais hotéis boutique de Portugal, reconhecido internacionalmente pela Condé Nast Traveller, pelo Guia MICHELIN e pelos The Plan Awards.\n\nA Pedra Silva Arquitectos teve ainda um papel central no desenvolvimento técnico da expansão do L''AND Vineyards, no Alentejo, em colaboração com o arquiteto Márcio Kogan (Studio MK27), sendo responsável pelo projeto de execução, documentação de concurso, licenciamento e coordenação com a câmara municipal e os projetistas de especialidades.\n\nOs clientes escolhem a Pedra Silva Arquitectos porque conjugamos:\n\n\n\n\n\nExperiência internacional em diversos projectos com um forte conhecimento local;\n\n\n\nArquitetura e design de interiores integrados quando necessário;\n\n\n\nVasta experiência em projeto de execução de edifícios complexos;\n\n\n\nCoordenação multidisciplinar com os projetistas de especialidades;\n\n\n\nExperiência comprovada desde o conceito até à conclusão da obra.\n\n"}, "contract_relevance": "proposal_only", "created_at": "2026-11-12T08:38:56.132506+00:00", "id": "1e683c82-2fbe-408f-b44f-98067e813562", "is_locked": false, "is_visible": true, "proposal_id": "3d0db6b3-4bf5-4681-a875-c553f8c64656", "sort_order": 200, "source_ref": {}, "source_type": "library", "title": "Porquê a Pedra Silva Arquitectos", "updated_at": "2026-11-13T14:35:52.189711+00:00"}}, {"before": {"id": "865c7a9f-fe66-4f62-8898-d08a8d80cbe6", "title": "Descrição do Projeto", "is_locked": false, "block_type": "scope", "created_at": "2026-11-07T18:55:18.931981+00:00", "is_visible": true, "sort_order": 50, "source_ref": {}, "updated_at": "2026-11-13T14:26:54.188211+00:00", "proposal_id": "3d0db6b3-4bf5-4681-a875-c553f8c64656", "source_type": "mixed", "content_rich": {"html": "<p>A nossa proposta refere-se à elaboração dos estudos e Projecto de Arquitectura e Assistência Técnica à execução da obra de reabilitação de um edifício localizado na esquina da Rua Nova do Almada com as Escadinhas de São Francisco (Rua Nova do Almada, 63-73, 1200-288 Lisboa), freguesia da Misericórdia, com o objetivo de o converter num estabelecimento hoteleiro.</p><p>A Pedra Silva Arquitectos (PSA) será a autora do projeto de arquitetura e a equipa projetista responsável pelo processo, trabalhando em parceria com o designer de interiores indicado pelo Cliente. A PSA irá desenvolver o estudo prévio,<span style=\"font-size: 14px;\">&nbsp;submeter o Pedido de Informação Prévia e o processo de licenciamento, preparar o projeto de execução, coordenar todos os projetos de especialidades e prestar assistência técnica à obra.</span></p><p>A proposta apresentada assenta na seguinte informação sobre o edifício existente:</p><ul><li><p>Informação prestada pelo promotor;</p></li><li><p>Conceito de design de interiores a fornecer pelo designer de interiores indicado pelo Cliente;</p></li><li><p>Consulta ao portal LXi para tomar conhecimento das condicionantes urbanísticas do edifício;</p></li><li><p>Análise das condicionantes para estabelecer um cenário possível de intervenção e, com isso, a prestação de serviços necessária para o promotor.</p></li></ul><p><strong>[Descrição do edifício existente e quadro de áreas – a completar.]</strong></p><p>Da análise das condicionantes do local, apresentamos uma proposta de prestação de serviços assente nas seguintes premissas:</p><ul><li><p>Reabilitação do edifício existente para instalação de um hotel, a licenciar como empreendimento turístico nos termos do Regime Jurídico dos Empreendimentos Turísticos (Decreto-Lei n.º 39/2008, na sua redação atual);</p></li><li><p>O número e a tipologia das unidades de alojamento, bem como as áreas comuns e de serviço, serão confirmados com o promotor e o designer de interiores na fase de Programa;</p></li><li><p>Em cada fase, a PSA só poderá desenvolver o seu trabalho após a receção dos elementos necessários por parte do Cliente e do designer de interiores. Caso estes elementos não sejam recebidos nos prazos acordados, a PSA não poderá ser responsabilizada por atrasos ou incumprimento de prazos.</p></li><li><p><strong>Repartição de responsabilidades:</strong> a PSA é responsável pelo projeto de arquitetura do edifício, incluindo as áreas técnicas e de serviço, a integração das soluções de interiores nos projetos de licenciamento e de execução e a coordenação geral das especialidades; o designer de interiores indicado pelo Cliente é responsável pelo conceito e projeto de design de interiores dos quartos e das áreas comuns, incluindo mobiliário, equipamento e decoração (FF&amp;E) e iluminação decorativa. A fronteira detalhada entre os dois âmbitos será confirmada na fase de Programa.</p></li></ul><p><strong>NOTA:</strong> As áreas indicadas servem de orientação para a elaboração da proposta de honorários e serão confirmadas com o levantamento arquitetónico do edifício.</p><p>Para além do projeto de Arquitetura e Plano de Acessibilidades, faz parte desta proposta:</p><ul><li><p>A coordenação dos diversos projetos de especialidades com o projeto de arquitetura;</p></li><li><p>A representação do requerente no portal Loja Lisboa e as submissões dos projetos no portal;</p></li><li><p>O acompanhamento do parecer do Turismo de Portugal, I.P., no âmbito do licenciamento do estabelecimento hoteleiro.</p></li></ul><p></p>", "text": "\n\nA nossa proposta refere-se à elaboração dos estudos e Projecto de Arquitectura e Assistência Técnica à execução da obra de reabilitação de um edifício localizado na esquina da Rua Nova do Almada com as Escadinhas de São Francisco (Rua Nova do Almada, 63-73, 1200-288 Lisboa), freguesia da Misericórdia, com o objetivo de o converter num estabelecimento hoteleiro.\n\n\n\nA Pedra Silva Arquitectos (PSA) será a autora do projeto de arquitetura e a equipa projetista responsável pelo processo, trabalhando em parceria com o designer de interiores indicado pelo Cliente. A PSA irá desenvolver o estudo prévio,\n\n submeter o Pedido de Informação Prévia e o processo de licenciamento, preparar o projeto de execução, coordenar todos os projetos de especialidades e prestar assistência técnica à obra.\n\n\n\n\n\nA proposta apresentada assenta na seguinte informação sobre o edifício existente:\n\n\n\n\n\n\n\nInformação prestada pelo promotor;\n\n\n\n\n\n\n\nConceito de design de interiores a fornecer pelo designer de interiores indicado pelo Cliente;\n\n\n\n\n\n\n\nConsulta ao portal LXi para tomar conhecimento das condicionantes urbanísticas do edifício;\n\n\n\n\n\n\n\nAnálise das condicionantes para estabelecer um cenário possível de intervenção e, com isso, a prestação de serviços necessária para o promotor.\n\n\n\n\n\n\n\n\n\n[Descrição do edifício existente e quadro de áreas – a completar.]\n\n\n\n\n\nDa análise das condicionantes do local, apresentamos uma proposta de prestação de serviços assente nas seguintes premissas:\n\n\n\n\n\n\n\nReabilitação do edifício existente para instalação de um hotel, a licenciar como empreendimento turístico nos termos do Regime Jurídico dos Empreendimentos Turísticos (Decreto-Lei n.º 39/2008, na sua redação atual);\n\n\n\n\n\n\n\nO número e a tipologia das unidades de alojamento, bem como as áreas comuns e de serviço, serão confirmados com o promotor e o designer de interiores na fase de Programa;\n\n\n\n\n\n\n\nEm cada fase, a PSA só poderá desenvolver o seu trabalho após a receção dos elementos necessários por parte do Cliente e do designer de interiores. Caso estes elementos não sejam recebidos nos prazos acordados, a PSA não poderá ser responsabilizada por atrasos ou incumprimento de prazos.\n\n\n\n\n\n\n\n\n\nRepartição de responsabilidades:\n\n a PSA é responsável pelo projeto de arquitetura do edifício, incluindo as áreas técnicas e de serviço, a integração das soluções de interiores nos projetos de licenciamento e de execução e a coordenação geral das especialidades; o designer de interiores indicado pelo Cliente é responsável pelo conceito e projeto de design de interiores dos quartos e das áreas comuns, incluindo mobiliário, equipamento e decoração (FF&E) e iluminação decorativa. A fronteira detalhada entre os dois âmbitos será confirmada na fase de Programa.\n\n\n\n\n\n\n\n\n\nNOTA:\n\n As áreas indicadas servem de orientação para a elaboração da proposta de honorários e serão confirmadas com o levantamento arquitetónico do edifício.\n\n\n\nPara além do projeto de Arquitetura e Plano de Acessibilidades, faz parte desta proposta:\n\n\n\n\n\n\n\nA coordenação dos diversos projetos de especialidades com o projeto de arquitetura;\n\n\n\n\n\n\n\nA representação do requerente no portal Loja Lisboa e as submissões dos projetos no portal;\n\n\n\n\n\n\n\nO acompanhamento do parecer do Turismo de Portugal, I.P., no âmbito do licenciamento do estabelecimento hoteleiro.\n\n\n\n\n\n\n\n\n\n"}, "contract_relevance": "both"}, "after": {"block_type": "scope", "content_rich": {"headingLevel": "h1", "html": "<p>A nossa proposta refere-se à elaboração dos estudos e Projecto de Arquitectura e Assistência Técnica à execução da obra de reabilitação de um edifício localizado na esquina da Rua Nova do Almada com as Escadinhas de São Francisco (Rua Nova do Almada, 63-73, 1200-288 Lisboa), freguesia da Misericórdia, com o objetivo de o converter num estabelecimento hoteleiro.</p><p>A Pedra Silva Arquitectos (PSA) será a autora do projeto de arquitetura e a equipa projetista responsável pelo processo, trabalhando em parceria com o designer de interiores indicado pelo Cliente. A PSA irá desenvolver o estudo prévio,<span style=\"font-size: 14px;\">&nbsp;submeter o Pedido de Informação Prévia e o processo de licenciamento, preparar o projeto de execução, coordenar todos os projetos de especialidades e prestar assistência técnica à obra.</span></p><p>A proposta apresentada assenta na seguinte informação sobre o edifício existente:</p><ul><li><p>Informação prestada pelo promotor;</p></li><li><p>Conceito de design de interiores a fornecer pelo designer de interiores indicado pelo Cliente;</p></li><li><p>Consulta ao portal LXi para tomar conhecimento das condicionantes urbanísticas do edifício;</p></li><li><p>Análise das condicionantes para estabelecer um cenário possível de intervenção e, com isso, a prestação de serviços necessária para o promotor.</p></li></ul><p><strong>[Descrição do edifício existente e quadro de áreas – a completar.]</strong></p><p>Da análise das condicionantes do local, apresentamos uma proposta de prestação de serviços assente nas seguintes premissas:</p><ul><li><p>Reabilitação do edifício existente para instalação de um hotel, a licenciar como empreendimento turístico nos termos do Regime Jurídico dos Empreendimentos Turísticos (Decreto-Lei n.º 39/2008, na sua redação atual);</p></li><li><p>O número e a tipologia das unidades de alojamento, bem como as áreas comuns e de serviço, serão confirmados com o promotor e o designer de interiores na fase de Programa;</p></li><li><p>Em cada fase, a PSA só poderá desenvolver o seu trabalho após a receção dos elementos necessários por parte do Cliente e do designer de interiores. Caso estes elementos não sejam recebidos nos prazos acordados, a PSA não poderá ser responsabilizada por atrasos ou incumprimento de prazos.</p></li><li><p><strong>Repartição de responsabilidades:</strong> a PSA é responsável pelo projeto de arquitetura do edifício, incluindo as áreas técnicas e de serviço, a integração das soluções de interiores nos projetos de licenciamento e de execução e a coordenação geral das especialidades; o designer de interiores indicado pelo Cliente é responsável pelo conceito e projeto de design de interiores dos quartos e das áreas comuns, incluindo mobiliário, equipamento e decoração (FF&amp;E) e iluminação decorativa. A fronteira detalhada entre os dois âmbitos será confirmada na fase de Programa.</p></li></ul><p><strong>NOTA:</strong> As áreas indicadas servem de orientação para a elaboração da proposta de honorários e serão confirmadas com o levantamento arquitetónico do edifício.</p><p>Para além do projeto de Arquitetura e Plano de Acessibilidades, faz parte desta proposta:</p><ul><li><p>A coordenação dos diversos projetos de especialidades com o projeto de arquitetura;</p></li><li><p>A representação do requerente no portal Loja Lisboa e as submissões dos projetos no portal;</p></li><li><p>O acompanhamento do parecer do Turismo de Portugal, I.P., no âmbito do licenciamento do estabelecimento hoteleiro.</p></li></ul><p></p>", "text": "\n\nA nossa proposta refere-se à elaboração dos estudos e Projecto de Arquitectura e Assistência Técnica à execução da obra de reabilitação de um edifício localizado na esquina da Rua Nova do Almada com as Escadinhas de São Francisco (Rua Nova do Almada, 63-73, 1200-288 Lisboa), freguesia da Misericórdia, com o objetivo de o converter num estabelecimento hoteleiro.\n\n\n\nA Pedra Silva Arquitectos (PSA) será a autora do projeto de arquitetura e a equipa projetista responsável pelo processo, trabalhando em parceria com o designer de interiores indicado pelo Cliente. A PSA irá desenvolver o estudo prévio,\n\n submeter o Pedido de Informação Prévia e o processo de licenciamento, preparar o projeto de execução, coordenar todos os projetos de especialidades e prestar assistência técnica à obra.\n\n\n\n\n\nA proposta apresentada assenta na seguinte informação sobre o edifício existente:\n\n\n\n\n\n\n\nInformação prestada pelo promotor;\n\n\n\n\n\n\n\nConceito de design de interiores a fornecer pelo designer de interiores indicado pelo Cliente;\n\n\n\n\n\n\n\nConsulta ao portal LXi para tomar conhecimento das condicionantes urbanísticas do edifício;\n\n\n\n\n\n\n\nAnálise das condicionantes para estabelecer um cenário possível de intervenção e, com isso, a prestação de serviços necessária para o promotor.\n\n\n\n\n\n\n\n\n\n[Descrição do edifício existente e quadro de áreas – a completar.]\n\n\n\n\n\nDa análise das condicionantes do local, apresentamos uma proposta de prestação de serviços assente nas seguintes premissas:\n\n\n\n\n\n\n\nReabilitação do edifício existente para instalação de um hotel, a licenciar como empreendimento turístico nos termos do Regime Jurídico dos Empreendimentos Turísticos (Decreto-Lei n.º 39/2008, na sua redação atual);\n\n\n\n\n\n\n\nO número e a tipologia das unidades de alojamento, bem como as áreas comuns e de serviço, serão confirmados com o promotor e o designer de interiores na fase de Programa;\n\n\n\n\n\n\n\nEm cada fase, a PSA só poderá desenvolver o seu trabalho após a receção dos elementos necessários por parte do Cliente e do designer de interiores. Caso estes elementos não sejam recebidos nos prazos acordados, a PSA não poderá ser responsabilizada por atrasos ou incumprimento de prazos.\n\n\n\n\n\n\n\n\n\nRepartição de responsabilidades:\n\n a PSA é responsável pelo projeto de arquitetura do edifício, incluindo as áreas técnicas e de serviço, a integração das soluções de interiores nos projetos de licenciamento e de execução e a coordenação geral das especialidades; o designer de interiores indicado pelo Cliente é responsável pelo conceito e projeto de design de interiores dos quartos e das áreas comuns, incluindo mobiliário, equipamento e decoração (FF&E) e iluminação decorativa. A fronteira detalhada entre os dois âmbitos será confirmada na fase de Programa.\n\n\n\n\n\n\n\n\n\nNOTA:\n\n As áreas indicadas servem de orientação para a elaboração da proposta de honorários e serão confirmadas com o levantamento arquitetónico do edifício.\n\n\n\nPara além do projeto de Arquitetura e Plano de Acessibilidades, faz parte desta proposta:\n\n\n\n\n\n\n\nA coordenação dos diversos projetos de especialidades com o projeto de arquitetura;\n\n\n\n\n\n\n\nA representação do requerente no portal Loja Lisboa e as submissões dos projetos no portal;\n\n\n\n\n\n\n\nO acompanhamento do parecer do Turismo de Portugal, I.P., no âmbito do licenciamento do estabelecimento hoteleiro.\n\n\n\n\n\n\n\n\n\n"}, "contract_relevance": "both", "created_at": "2026-11-07T18:55:18.931981+00:00", "id": "865c7a9f-fe66-4f62-8898-d08a8d80cbe6", "is_locked": false, "is_visible": true, "proposal_id": "3d0db6b3-4bf5-4681-a875-c553f8c64656", "sort_order": 300, "source_ref": {}, "source_type": "mixed", "title": "Descrição do Projeto", "updated_at": "2026-11-13T14:35:52.189711+00:00"}}, {"before": {"id": "0c578d0c-d7b6-4290-8521-8c39a1a06703", "title": "Organização do Projeto e Fases", "is_locked": false, "block_type": "stage_list", "created_at": "2026-11-07T18:55:18.931981+00:00", "is_visible": true, "sort_order": 60, "source_ref": {}, "updated_at": "2026-11-12T16:29:47.289024+00:00", "proposal_id": "3d0db6b3-4bf5-4681-a875-c553f8c64656", "source_type": "live_quote", "content_rich": {"html": "<p>Propõe-se que o projeto se organize nas fases abaixo, divididas entre a <strong>Fase de Projeto</strong> e a <strong>Fase de Obra</strong>. O início de cada fase está dependente da aprovação da fase anterior pelo cliente.</p>", "text": "Propõe-se que o projeto se organize nas fases abaixo, divididas entre a Fase de Projeto e a Fase de Obra. O início de cada fase está dependente da aprovação da fase anterior pelo cliente."}, "contract_relevance": "both"}, "after": {"block_type": "stage_list", "content_rich": {"headingLevel": "h1", "html": "<p>Propõe-se que o projeto se organize nas fases abaixo, divididas entre a <strong>Fase de Projeto</strong> e a <strong>Fase de Obra</strong>. O início de cada fase está dependente da aprovação da fase anterior pelo cliente.</p>", "text": "Propõe-se que o projeto se organize nas fases abaixo, divididas entre a Fase de Projeto e a Fase de Obra. O início de cada fase está dependente da aprovação da fase anterior pelo cliente."}, "contract_relevance": "both", "created_at": "2026-11-07T18:55:18.931981+00:00", "id": "0c578d0c-d7b6-4290-8521-8c39a1a06703", "is_locked": false, "is_visible": true, "proposal_id": "3d0db6b3-4bf5-4681-a875-c553f8c64656", "sort_order": 400, "source_ref": {}, "source_type": "live_quote", "title": "Organização do Projeto e Fases", "updated_at": "2026-11-13T14:35:52.189711+00:00"}}, {"before": {"id": "db9736ec-ce7b-4482-8750-5a234a3b4be2", "title": "Fase (cópia)", "is_locked": false, "block_type": "stage_item", "created_at": "2026-11-08T11:35:46.561411+00:00", "is_visible": true, "sort_order": 70, "source_ref": {"stage_id": "1ab49e43-b963-4693-ac47-d912a49bc1e3"}, "updated_at": "2026-11-13T14:26:54.188211+00:00", "proposal_id": "3d0db6b3-4bf5-4681-a875-c553f8c64656", "source_type": "live_quote", "content_rich": {"client_info": "Levantamento arquitetónico do edifício, por técnico credenciado\nDesenhos existentes do edifício em formato DWG (editável), quando disponíveis\nPrograma e objetivos do promotor e normas do operador hoteleiro\nLimites orçamentais da obra\nDocumentação do imóvel (caderneta predial e certidão do registo predial)", "deliverables": "Síntese das condicionantes urbanísticas e regulamentares.\nPrograma do hotel (unidades de alojamento, áreas comuns e de serviço), desenvolvido com o Cliente e o designer de interiores.", "headingLevel": "h2", "objective_html": "<p>O Programa faz parte desta prestação de serviços e é desenvolvido pela PSA em conjunto com o Cliente e o designer de interiores por ele indicado.</p><p>Nesta fase, a PSA reúne e analisa toda a informação relevante para o desenvolvimento do Projeto – as condicionantes urbanísticas, os requisitos de classificação do estabelecimento hoteleiro, as normas do operador e os limites orçamentais – de modo a preparar o desenvolvimento do Estudo Prévio.</p>", "objective_text": "O Programa faz parte desta prestação de serviços e é desenvolvido pela PSA em conjunto com o Cliente e o designer de interiores por ele indicado.\n\nNesta fase, a PSA reúne e analisa toda a informação relevante para o desenvolvimento do Projeto – as condicionantes urbanísticas, os requisitos de classificação do estabelecimento hoteleiro, as normas do operador e os limites orçamentais – de modo a preparar o desenvolvimento do Estudo Prévio.", "key_activities_html": "<ul><li><p>Visita ao local / reunião com o cliente e o designer de interiores;</p></li><li><p>Consulta de elementos sobre o edifício (no arquivo municipal ou outros);</p></li><li><p>Consulta da legislação aplicável à intervenção, incluindo o regime jurídico dos empreendimentos turísticos e os requisitos de classificação dos estabelecimentos hoteleiros;</p></li><li><p>Eventual agendamento de reunião com a Câmara Municipal de Lisboa para esclarecimentos.</p></li></ul><p></p>", "key_activities_text": "\n\n\n\nVisita ao local / reunião com o cliente e o designer de interiores;\n\n\n\n\n\n\n\nConsulta de elementos sobre o edifício (no arquivo municipal ou outros);\n\n\n\nConsulta da legislação aplicável à intervenção, incluindo o regime jurídico dos empreendimentos turísticos e os requisitos de classificação dos estabelecimentos hoteleiros;\n\n\n\nEventual agendamento de reunião com a Câmara Municipal de Lisboa para esclarecimentos.\n\n", "stage_approval_html": "<p>No final desta fase, o cliente aprova o Programa, que servirá de referência para o Estudo Prévio. O Cliente dispõe de 5 dias úteis após a entrega para aprovar a fase. Na ausência de resposta findo este prazo, a fase considera-se aprovada por ambas as partes.</p><p><strong>NOTA:</strong> Para iniciar o estudo serão necessárias bases de trabalho fundamentais para a sua realização, designadamente o levantamento arquitetónico do edifício, feito por técnico credenciado.</p>", "stage_approval_text": "No final desta fase, o cliente aprova o Programa, que servirá de referência para o Estudo Prévio. O Cliente dispõe de 5 dias úteis após a entrega para aprovar a fase. Na ausência de resposta findo este prazo, a fase considera-se aprovada por ambas as partes.\n\nNOTA: Para iniciar o estudo serão necessárias bases de trabalho fundamentais para a sua realização, designadamente o levantamento arquitetónico do edifício, feito por técnico credenciado."}, "contract_relevance": "both"}, "after": {"block_type": "stage_item", "content_rich": {"client_info": "Levantamento arquitetónico do edifício, por técnico credenciado\nDesenhos existentes do edifício em formato DWG (editável), quando disponíveis\nPrograma e objetivos do promotor e normas do operador hoteleiro\nLimites orçamentais da obra\nDocumentação do imóvel (caderneta predial e certidão do registo predial)", "deliverables": "Síntese das condicionantes urbanísticas e regulamentares.\nPrograma do hotel (unidades de alojamento, áreas comuns e de serviço), desenvolvido com o Cliente e o designer de interiores.", "headingLevel": "h1", "key_activities_html": "<ul><li><p>Visita ao local / reunião com o cliente e o designer de interiores;</p></li><li><p>Consulta de elementos sobre o edifício (no arquivo municipal ou outros);</p></li><li><p>Consulta da legislação aplicável à intervenção, incluindo o regime jurídico dos empreendimentos turísticos e os requisitos de classificação dos estabelecimentos hoteleiros;</p></li><li><p>Eventual agendamento de reunião com a Câmara Municipal de Lisboa para esclarecimentos.</p></li></ul><p></p>", "key_activities_text": "\n\n\n\nVisita ao local / reunião com o cliente e o designer de interiores;\n\n\n\n\n\n\n\nConsulta de elementos sobre o edifício (no arquivo municipal ou outros);\n\n\n\nConsulta da legislação aplicável à intervenção, incluindo o regime jurídico dos empreendimentos turísticos e os requisitos de classificação dos estabelecimentos hoteleiros;\n\n\n\nEventual agendamento de reunião com a Câmara Municipal de Lisboa para esclarecimentos.\n\n", "objective_html": "<p>O Programa faz parte desta prestação de serviços e é desenvolvido pela PSA em conjunto com o Cliente e o designer de interiores por ele indicado.</p><p>Nesta fase, a PSA reúne e analisa toda a informação relevante para o desenvolvimento do Projeto – as condicionantes urbanísticas, os requisitos de classificação do estabelecimento hoteleiro, as normas do operador e os limites orçamentais – de modo a preparar o desenvolvimento do Estudo Prévio.</p>", "objective_text": "O Programa faz parte desta prestação de serviços e é desenvolvido pela PSA em conjunto com o Cliente e o designer de interiores por ele indicado.\n\nNesta fase, a PSA reúne e analisa toda a informação relevante para o desenvolvimento do Projeto – as condicionantes urbanísticas, os requisitos de classificação do estabelecimento hoteleiro, as normas do operador e os limites orçamentais – de modo a preparar o desenvolvimento do Estudo Prévio.", "stage_approval_html": "<p>No final desta fase, o cliente aprova o Programa, que servirá de referência para o Estudo Prévio. O Cliente dispõe de 5 dias úteis após a entrega para aprovar a fase. Na ausência de resposta findo este prazo, a fase considera-se aprovada por ambas as partes.</p><p><strong>NOTA:</strong> Para iniciar o estudo serão necessárias bases de trabalho fundamentais para a sua realização, designadamente o levantamento arquitetónico do edifício, feito por técnico credenciado.</p>", "stage_approval_text": "No final desta fase, o cliente aprova o Programa, que servirá de referência para o Estudo Prévio. O Cliente dispõe de 5 dias úteis após a entrega para aprovar a fase. Na ausência de resposta findo este prazo, a fase considera-se aprovada por ambas as partes.\n\nNOTA: Para iniciar o estudo serão necessárias bases de trabalho fundamentais para a sua realização, designadamente o levantamento arquitetónico do edifício, feito por técnico credenciado."}, "contract_relevance": "both", "created_at": "2026-11-08T11:35:46.561411+00:00", "id": "db9736ec-ce7b-4482-8750-5a234a3b4be2", "is_locked": false, "is_visible": true, "proposal_id": "3d0db6b3-4bf5-4681-a875-c553f8c64656", "sort_order": 500, "source_ref": {"stage_id": "1ab49e43-b963-4693-ac47-d912a49bc1e3"}, "source_type": "live_quote", "title": "Programa", "updated_at": "2026-11-13T14:35:52.189711+00:00"}}, {"before": {"id": "2d9b0662-984c-41a7-b518-97baea89035b", "title": "Fase", "is_locked": false, "block_type": "stage_item", "created_at": "2026-11-07T18:55:18.931981+00:00", "is_visible": true, "sort_order": 80, "source_ref": {"stage_id": "2f5ed408-f41c-46f3-aa4d-88dbec4b135e"}, "updated_at": "2026-11-13T14:26:54.188211+00:00", "proposal_id": "3d0db6b3-4bf5-4681-a875-c553f8c64656", "source_type": "live_quote", "content_rich": {"client_info": "Aprovação do Programa\nLevantamento arquitetónico do edifício em formato DWG (editável)\nNomes e contactos das equipas escolhidas para o projeto", "deliverables": "Relatório da fase com descrição escrita do projeto.\nLayout final com todas as alterações pretendidas pelo Cliente.\nPlantas de todos os pisos, cortes e alçados – escala 1:100.\nQuadro de áreas e de quartos.\nEntrega em formato digital e 2 conjuntos impressos.", "headingLevel": "h2", "objective_html": "<p>Depois de definido e aprovado o Programa, vamos elaborar, em articulação com o designer de interiores, o Estudo Prévio do hotel, desenvolvendo os conceitos definidos e apresentando soluções através de desenhos e outros elementos que facilitem a compreensão do projeto, da sua organização e da sua aparência final.</p><p>Iremos definir a globalidade da intervenção, fixando o layout final com todas as alterações pretendidas pelo Cliente, dentro do contexto da legislação em vigor para o local, e estudar a melhor estratégia de encaminhar o processo para a obtenção da aprovação camarária.</p><p>É ainda nosso papel consultar os projetistas das especialidades para, em conjunto com estes, estudar as soluções do ponto de vista técnico, construtivo e de custos.</p>", "objective_text": "Depois de definido e aprovado o Programa, vamos elaborar, em articulação com o designer de interiores, o Estudo Prévio do hotel, desenvolvendo os conceitos definidos e apresentando soluções através de desenhos e outros elementos que facilitem a compreensão do projeto, da sua organização e da sua aparência final.\n\nIremos definir a globalidade da intervenção, fixando o layout final com todas as alterações pretendidas pelo Cliente, dentro do contexto da legislação em vigor para o local, e estudar a melhor estratégia de encaminhar o processo para a obtenção da aprovação camarária.\n\nÉ ainda nosso papel consultar os projetistas das especialidades para, em conjunto com estes, estudar as soluções do ponto de vista técnico, construtivo e de custos.", "key_activities_html": "<ul><li><p>Reunião inicial com o Cliente e o designer de interiores para confirmar o Programa e os objetivos do projeto;</p></li><li><p>Apresentação de toda a equipa do projeto, das especialidades ao design de interiores;</p></li><li><p>Estudos do layout definitivo dos vários pisos e dos quartos;</p></li><li><p>Estudos de cortes, alçados e volumetria;</p></li><li><p>Cálculo de áreas, cérceas e índices a cumprir;</p></li><li><p>Verificação preliminar dos requisitos de classificação do estabelecimento hoteleiro;</p></li><li><p>Coordenação da equipa de projeto e verificação da compatibilização de todos os projetos. Todas as alterações pretendidas pelo Cliente devem ser fechadas até à conclusão desta fase.</p></li></ul><p></p>", "key_activities_text": "\n\n\n\nReunião inicial com o Cliente e o designer de interiores para confirmar o Programa e os objetivos do projeto;\n\n\n\nApresentação de toda a equipa do projeto, das especialidades ao design de interiores;\n\n\n\nEstudos do layout definitivo dos vários pisos e dos quartos;\n\n\n\nEstudos de cortes, alçados e volumetria;\n\n\n\nCálculo de áreas, cérceas e índices a cumprir;\n\n\n\nVerificação preliminar dos requisitos de classificação do estabelecimento hoteleiro;\n\n\n\nCoordenação da equipa de projeto e verificação da compatibilização de todos os projetos. Todas as alterações pretendidas pelo Cliente devem ser fechadas até à conclusão desta fase.\n\n", "stage_approval_html": "<p>Prevemos ir ao encontro dos seus objetivos através da apresentação de uma proposta de estudo prévio, desenvolvida durante o tempo estimado e com os recursos previstos no planeamento apresentado. A nossa equipa fará as necessárias afinações de forma a obter a sua total satisfação, desde que estas estejam dentro do número de horas previsto na nossa proposta de honorários.</p><p>O Cliente dispõe de 5 dias úteis após a entrega para aprovar a fase. Na ausência de resposta findo este prazo, a fase considera-se aprovada por ambas as partes.</p>", "stage_approval_text": "Prevemos ir ao encontro dos seus objetivos através da apresentação de uma proposta de estudo prévio, desenvolvida durante o tempo estimado e com os recursos previstos no planeamento apresentado. A nossa equipa fará as necessárias afinações de forma a obter a sua total satisfação, desde que estas estejam dentro do número de horas previsto na nossa proposta de honorários.\n\nO Cliente dispõe de 5 dias úteis após a entrega para aprovar a fase. Na ausência de resposta findo este prazo, a fase considera-se aprovada por ambas as partes."}, "contract_relevance": "both"}, "after": {"block